{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment. Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets.",
      "reason": "The abstract describes the current state of knowledge regarding malaria control progress, the financial gap, and the role of optimization models in addressing constrained budgets."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The abstract clearly states the aim of the review, which establishes the need to identify, characterize, and assess the strengths and limitations of existing models for resource allocation."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that this is an update or replication of a previous systematic review, nor does it mention the existence of similar systematic reviews that necessitate this specific work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of 'models for malaria control optimization', not a review of the effects of a specific intervention itself (e.g., a clinical trial meta-analysis). Therefore, a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review focuses on optimization models rather than evaluating a complex intervention or delivery context that would require a logic model to show hypothesized relationships between components and outcomes."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review explicitly states both the research question and the main aim/objective of the study."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of models for malaria control optimization, not a review of intervention effects (e.g., a comparative effectiveness review of specific clinical interventions), so PICO comparisons are not applicable."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024; (3) Studies were included irrespective of the targeted geographical regions; (4) Studies were included irrespective of the population subgroups; (5) Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "The manuscript explicitly lists the inclusion criteria, covering study type (peer-reviewed journals), language (English), publication date, population (human Plasmodium species), model type (optimization model), intervention count (two or more), and data requirements (cost data, outcomes/health benefits)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024",
      "reason": "The manuscript specifies report characteristics including publication status (peer-reviewed journals), language (English), and publication date (before 30th June 2024)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not appear to have excluded studies specifically because outcomes were not measured versus not reported; the exclusion criteria provided in the text (chunk_id: text_9) focus on study type, language, and publication type, and the PRISMA diagram (figure_3) lists reasons for exclusion (e.g., 'No optimisation model', 'One intervention only') which do not pertain to this specific distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "A narrative synthesis of the study characteristics was performed. All studies investigated WHO-recommended interventions for control or elimination targets (Table 2)... The administrative level of data analysis (Table 4) varied between national/multinational only (40.0%), national/ Table 2 Summary of models for malaria control optimization studies",
      "reason": "The manuscript describes the synthesis approach (narrative synthesis) and groups studies based on characteristics such as interventions (Table 2), region of focus, and administrative level of analysis, which are linked to the review's objective of characterizing models for malaria control optimization."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report any notable restrictions on study eligibility that would require a specific rationale beyond standard systematic review criteria."
    }
  ],
  "confidence": 100
}

